// ═══ ASSERT: internal invariant check ═══
private BigDecimal calculateInterest(BigDecimal balance, BigDecimal rate) {
    assert balance != null : "balance must not be null — internal bug!";
    assert rate.signum() >= 0 : "rate must be non-negative — internal bug!";
    // If balance IS null with -ea → AssertionError thrown
    // WITHOUT -ea (production default) → assert COMPLETELY SKIPPED! Zero cost.
    return balance.multiply(rate);
}

// ═══ WRONG: assert for public API validation ═══
public void withdraw(BigDecimal amount) {
    assert amount.signum() > 0 : "amount must be positive";
    // (Avoid) DANGEROUS! In production (-ea NOT set): this assert is SKIPPED!
    // User passes -100 → no validation → negative withdrawal!
    balance = balance.subtract(amount);  // balance CORRUPTED!
}

// ═══ CORRECT: exception for public API validation ═══
public void withdraw(BigDecimal amount) {
    if (amount == null || amount.signum() <= 0) {
        throw new IllegalArgumentException("Amount must be positive: " + amount);
        // (Recommended) ALWAYS active! Production or development. Cannot be disabled.
    }
    balance = balance.subtract(amount);
}

// ═══ ENABLE/DISABLE ═══
// java -ea MyApp        → assertions ENABLED (development/testing)
// java MyApp            → assertions DISABLED (production default)
// java -ea:com.bank... → enable for specific package only
