// (Recommended) INTERNAL invariants — checking YOUR code's assumptions:
private void processSettlement(Trade trade) {
    // At this point, trade MUST be validated by the service layer above.
    // If it's not → MY code has a bug in the call chain.
    assert trade.getStatus().equals("VALIDATED") : "Bug: trade not validated before settlement!";
    // This catches DEVELOPER errors, not user errors.
}

// (Recommended) Post-condition checks (method promises):
private List<Trade> filterSettled(List<Trade> trades) {
    List<Trade> result = trades.stream().filter(Trade::isSettled).toList();
    assert result.stream().allMatch(Trade::isSettled) : "Bug: non-settled trade in result!";
    return result;
    // If this assert fails → the filter logic has a bug.
}

// (Recommended) Unreachable code:
switch (status) {
    case "SETTLED" -> process();
    case "PENDING" -> queue();
    case "FAILED" -> retry();
    default -> { assert false : "Bug: unknown status: " + status; }
    // If we reach default → missing case in our code.
}
