package com.bank.assertdemo;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class AssertKeywordTest {

    @Test
    void assertDisabledByDefault() {
        // Assertions are typically DISABLED in test runners too (depends on config).
        // To test assert behavior, we simulate:
        boolean assertionsEnabled = false;
        try {
            assert false;  // if enabled, throws AssertionError
        } catch (AssertionError e) {
            assertionsEnabled = true;
        }
        // assertionsEnabled depends on JVM flags — not guaranteed in tests!
        System.out.println("Assertions enabled: " + assertionsEnabled);
    }

    @Test
    void illegalArgumentException_alwaysActive() {
        // This ALWAYS works — production or development:
        assertThatThrownBy(() -> {
            java.math.BigDecimal amount = new java.math.BigDecimal("-100");
            if (amount.signum() <= 0) throw new IllegalArgumentException("positive required");
        }).isInstanceOf(IllegalArgumentException.class);
        // Cannot be disabled! SAFE for public API validation.
    }

    @Test
    void assertVsException_comparison() {
        // assert:
        //   Disabled by default (-ea to enable)
        //   For: internal invariants, developer bugs
        //   Throws: AssertionError (Error — don't catch!)
        //   NEVER for: public API, security, production logic

        // Exception (IllegalArgumentException, Objects.requireNonNull):
        //   ALWAYS active
        //   For: public API validation, user input
        //   Throws: RuntimeException
        //   Use for: ALL production validation
        assertThat(true).isTrue();
    }
}
